INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 0.0, "クローチェ", 126401, 1, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", 1, "2023/06/30 12:00:00", 1.47, 2002, "2023/09/22 14:59:59", 2, 10001, -470.0);
