INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 0.0, "ライラエル", 126501, 2, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 1, "2023/06/30 12:00:00", 0.0, 2002, "2023/09/22 14:59:59", 2, 10003, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 0.0, "ライラエル", 126501, 1, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 2, "2023/06/30 12:00:00", 0.0, 2002, "2023/09/22 14:59:59", 1, 10004, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 0.0, "リンド", 127702, 2, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 1, "2023/09/15 15:00:00", 0.0, 2002, "2023/12/22 14:59:59", 2, 10005, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 0.0, "リンド", 127702, 2, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 2, "2023/09/15 15:00:00", 0.0, 2002, "2023/12/22 14:59:59", 2, 10006, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 0.0, "ヴルム", 127802, 1, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 1, "2023/09/15 15:00:00", 0.0, 2002, "2023/12/22 14:59:59", 1, 10007, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 0.0, "ヴルム", 127802, 2, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 2, "2023/09/15 15:00:00", 6.5, 2002, "2023/12/22 14:59:59", 1, 10008, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, 0.0, "アネモネ", 129602, 2, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 1, "2023/12/15 15:00:00", 0.0, 2002, "2024/03/22 14:59:59", 1, 10009, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, 0.0, "アネモネ", 129602, 2, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 2, "2023/12/15 15:00:00", 0.0, 2002, "2024/03/22 14:59:59", 1, 10010, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, 0.0, "ネフィ=ネラ", 129701, 1, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 1, "2023/12/15 15:00:00", 0.0, 2002, "2024/03/22 14:59:59", 1, 10011, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, 0.0, "ネフィ=ネラ", 129701, 2, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 2, "2023/12/15 15:00:00", 6.2, 2002, "2024/03/22 14:59:59", 1, 10012, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, 0.0, "カノン", 130301, 3, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 1, "2024/03/15 15:00:00", 3.1, 2002, "2024/06/22 14:59:59", 5, 10013, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, 0.0, "カノン", 130301, 3, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 2, "2024/03/15 15:00:00", 6.15, 2002, "2024/06/22 14:59:59", 2, 10014, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, 0.0, "ナーナ", 130401, 2, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 1, "2024/03/15 15:00:00", 0.0, 2002, "2024/06/22 14:59:59", 2, 10015, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, 0.0, "ナーナ", 130401, 2, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 2, "2024/03/15 15:00:00", 3.35, 2002, "2024/06/22 14:59:59", 1, 10016, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 0.0, "ホウオウ", 130502, 1, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 1, "2024/06/15 15:00:00", 0.0, 2002, "2024/09/22 14:59:59", 1, 10017, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 0.0, "ホウオウ", 130502, 2, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 2, "2024/06/15 15:00:00", 3.18, 2002, "2024/09/22 14:59:59", 1, 10018, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 0.0, "ホウオウ", 130503, 4, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 3, "2024/06/15 15:00:00", 0.0, 2002, "2024/09/22 14:59:59", 4, 10019, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 0.0, "ネア", 123301, 1, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 1, "2024/06/15 15:00:00", 4.9, 2002, "2024/09/22 14:59:59", 2, 10020, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 0.0, "ネア", 123301, 1, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 2, "2024/06/15 15:00:00", 4.8, 2002, "2024/09/22 14:59:59", 2, 10021, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, 0.0, "カリザ", 133301, 3, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 1, "2024/09/15 15:00:00", 4.922, 2002, "2024/12/22 14:59:59", 1, 10022, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, 0.0, "カリザ", 133301, 3, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 2, "2024/09/15 15:00:00", 9.638, 2002, "2024/12/22 14:59:59", 5, 10023, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, 0.0, "ミーア", 133401, 1, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 1, "2024/09/15 15:00:00", 2.88, 2002, "2024/12/22 14:59:59", 2, 10024, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, 0.0, "ミーア", 133401, 5, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 2, "2024/09/15 15:00:00", 4.818, 2002, "2024/12/22 14:59:59", 1, 10025, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, 0.0, "グレイス", 133002, 2, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 1, "2024/12/15 15:00:00", 1.78, 2002, "2025/03/22 14:59:59", 1, 10026, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, 0.0, "グレイス", 133002, 1, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 2, "2024/12/15 15:00:00", 6.15, 2002, "2025/03/22 14:59:59", 7, 10027, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, 0.0, "ヴァイオレット", 133102, 6, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 1, "2024/12/15 15:00:00", 4.28, 2002, "2025/03/22 14:59:59", 2, 10028, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, 0.0, "ヴァイオレット", 133102, 1, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 2, "2024/12/15 15:00:00", 0.0, 2002, "2025/03/22 14:59:59", 1, 10029, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, 0.0, "ルルィ", 136902, 2, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 1, "2025/03/15 15:00:00", 5.53, 2002, "2025/06/23 14:59:59", 1, 10030, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, 0.0, "ルルィ", 136902, 9, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 2, "2025/03/15 15:00:00", 6.05, 2002, "2025/06/23 14:59:59", 7, 10031, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, 0.0, "デュラン", 137001, 2, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 1, "2025/03/15 15:00:00", 0.0, 2002, "2025/06/23 14:59:59", 1, 10032, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, 0.0, "デュラン", 137001, 2, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 2, "2025/03/15 15:00:00", 0.0, 2002, "2025/06/23 14:59:59", 1, 10033, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, 0.0, "サツキ", 135902, 2, "おう\n好きなもん持ってきな", 1, "2025/06/16 15:00:00", 0.0, 2002, "2025/09/23 14:59:59", 2, 10034, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, 0.0, "サツキ", 135902, 1, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 2, "2025/06/16 15:00:00", 4.935, 2002, "2025/09/23 14:59:59", 6, 10035, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, 0.0, "ユキノ", 135802, 2, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 1, "2025/06/16 15:00:00", 7.441, 2002, "2025/09/23 14:59:59", 5, 10036, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, 0.0, "ユキノ", 135802, 7, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 2, "2025/06/16 15:00:00", 0.0, 2002, "2025/09/23 14:59:59", 7, 10037, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, 0.0, "クルル", 130901, 2, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 1, "2025/09/16 15:00:00", 2.295, 2002, "2025/12/22 14:59:59", 2, 10038, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, 0.0, "クルル", 130901, 1, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 2, "2025/09/16 15:00:00", 6.281, 2002, "2025/12/22 14:59:59", 6, 10039, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, 0.0, "ヴォルガーノ", 137701, 2, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 1, "2025/09/16 15:00:00", 5.549, 2002, "2025/12/22 14:59:59", 1, 10040, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, 0.0, "ヴォルガーノ", 137701, 3, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 2, "2025/09/16 15:00:00", 2.64, 2002, "2025/12/22 14:59:59", 6, 10041, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, 0.0, "ライラエル", 132801, 7, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 1, "2025/12/15 15:00:00", 7.642, 2002, "2026/03/23 11:59:59", 4, 10042, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, 0.0, "ライラエル", 132802, 1, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 2, "2025/12/15 15:00:00", 0.0, 2002, "2026/03/23 11:59:59", 1, 10043, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, 0.0, "クローチェ", 134502, 1, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 1, "2025/12/15 15:00:00", 0.0, 2002, "2026/03/23 11:59:59", 1, 10044, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, 0.0, "クローチェ", 134501, 2, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 2, "2025/12/15 15:00:00", 3.72, 2002, "2026/03/23 11:59:59", 1, 10045, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, 0.0, "ネフィ＝ネラ", 138201, 2, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 1, "2026/03/16 12:00:00", 4.991, 2002, "2026/06/22 11:59:59", 1, 10046, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, 0.0, "ネフィ＝ネラ", 138201, 1, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 2, "2026/03/16 12:00:00", 3.877, 2002, "2026/06/22 11:59:59", 4, 10047, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, 0.0, "アラクネ", 136001, 4, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 1, "2026/03/16 12:00:00", 1.71, 2002, "2026/06/22 11:59:59", 6, 10048, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, 0.0, "アラクネ", 136001, 5, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 2, "2026/03/16 12:00:00", 5.32, 2002, "2026/06/22 11:59:59", 2, 10049, -470.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (13, 0.0, "アネモネ", 135401, 9, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 1, "2026/06/15 12:00:00", 3.727, 2002, "2026/09/22 11:59:59", 4, 10050, -470.0);
